; c10_peri_xfer_pub -- Peri: EXEC_XFER, EXEC_PUB, and Main taking the result
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: DeviceMap packing and index (D3); XferOneByte / XferMultiByte descriptors; PeriPublishDesc; PERI_RESULT_META; the result slot
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c10_peri_xfer_pub.expected.csv
.include "conf_defs.inc"
.service SID_TEST = 3
.devmap 0, I2C, 0x55, DEV_OTHER            ; entry 0 is NOT the one used: an access to 0x55 means the index is read wrongly
.devmap 1, I2C, 0x2A, DEV_TEST
.main
wait:
    BR.COND PERI_RESULT_VALID, take
    JMP wait
take:
    MOV PERI_RESULT_META[0..0] -> MAIN_SCRATCHPAD[0..0]       ; the service id (before the slot is consumed)
    EXEC_CSR WRITE_SP RES + 0, len=1, ptr=0
    MOV PERI_RESULT_SLOT[0..4] -> MAIN_SCRATCHPAD[4..8]       ; consumes the result
    EXEC_CSR WRITE_SP RES + 4, len=5, ptr=4
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
.peri
    EXEC_CSR WRITE8 RES + 32, 0x9E             ; Peri reaches the CSRs too
    EXEC_XFER WRITE dev=DEV_TEST, addr=0x30, addrlen=1, data=0x77
    EXEC_XFER READ  dev=DEV_TEST, addr=0x10, addrlen=1, ptr=0
    EXEC_XFER READ  dev=DEV_TEST, len=4, ptr=1, ext=[0x20]
    EXEC_PUB service=SID_TEST, src=0, len=5
pdone:
    JMP pdone
